import{z as l,x as i,o as A,c as s,q as r,j as B,D as e,d as n,s as d,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"断点回归的加深","description":"","frontmatter":{"title":"断点回归的加深","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/pe-rdd-deep.md","filePath":"econ/pe-rdd-deep.md","lastUpdated":1791413859000}'),p={name:"econ/pe-rdd-deep.md"};function C(m,E,u,D,c,h){const t=i("Mermaid");return A(),s("div",null,[E[2]||(E[2]=r('<h1 id="断点回归的加深" tabindex="-1">断点回归的加深 <a class="header-anchor" href="#断点回归的加深" aria-label="Permalink to &quot;断点回归的加深&quot;">​</a></h1><div class="epigraph"><p>断点给出的因果是一英寸宽的世界；加深不是把这结论推宽，而是把这一英寸钉得更牢——带宽、操纵、离散驱动元，每一处都是钉子。</p><footer>—— Imbens and Kalyanaraman, REStud 2012；Calonico, Cattaneo and Titiunik, Econometrica 2014；Gelman and Imbens 2019</footer></div><p><a href="/econ/pe-staggered-did-revisions">上一课</a>把交错面板的目标参数钉在聚合与对照上。本课回到截面门槛设计。主干<a href="/econ/rdd">断点回归</a>钉了清晰与模糊、局部多项式、Imbens–Kalyanaraman 与 CCT 带宽、McCrary 密度；本课加深四处：带宽内的偏误-方差账、操纵检验的升级、离散驱动元的另一套推断、从门槛外推的声明。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>带宽不是细节，是识别的一部分。CCT 的偏误校正把门槛附近曲率差扣掉，代价是方差上升；带宽每变一次，\\(\\tau\\) 就变一次——不报敏感性，等于把一个中间值伪装成常数。操纵检验同样要升级：McCrary 密度只能抓「可操纵且想操纵」的驱动元，分数恰在门槛附近的平滑密度不能排除研究者没见过的操纵；所以密度检验要与<strong>协变量 bundle</strong> 并用——基线协变量在 \\(c\\) 处都不跳，是局部随机这一句话的另一组可证伪读数。离散驱动元是第三处：考试成绩整数、票数按席计，密度在门槛附近没有意义，质量点之间没有「几乎一样」的邻居，局部随机化推断（Cattaneo、Frandsen 与 Titiunik）换成「\\(c-1\\) 与 \\(c\\) 两个质量点的精确随机化检验」。第四处是外推：\\(\\tau\\) 只在 \\(c\\) 的一英寸内成立，全局政策乘数要另加结构或分布外推假设，并显式声明。</p><p><span class="marginnote">数字实例：带宽 \\(h\\) 的偏误-方差账可以数出来。带宽内样本量大约与 \\(h\\) 成正比：\\(h=5\\) 分时门槛附近可能有 800 人，方差小、但门槛两侧曲率差被扫进来，偏误大；\\(h=2\\) 分时只剩 300 人，偏误小、置信区间宽出六成以上。所以任何单一带宽的 \\(\\hat\\tau\\) 都不是「答案」，\\(h\\)、\\(\\tfrac12 h\\)、\\(2h\\) 三档一致才敢往下写。</span></p><p><span class="marginnote">Gelman–Imbens 的警告值得钉在墙上：全局高阶多项式在支撑两端的摆动能造出假断点。阶数是一或二的局部拟合加带宽敏感性，默认没有「拟合得越平滑越好」这回事。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流程按驱动元分岔。连续驱动元：CCT 稳健偏误校正估计，报 \\(h\\)、\\(\\tfrac12 h\\)、\\(2h\\) 三档敏感性；协变量只作精度与平衡检验，不作条件化的借口；donut 稳健性——剔除 \\(c\\pm\\delta\\) 再估计，对付恰在门槛上的精确操纵，代价是局部性更强、带宽内的样本更少。<span class="marginnote">术语翻译：donut（甜甜圈）就是把门槛两侧 \\(\\pm\\delta\\) 分内的观测整个挖掉、只用剩下的「圈」重新估计。若有人把 58 分改成 60 分刚好过线，这些被操纵的观测恰好住在被挖掉的中心里；估计结论若在挖与不挖之间稳定，操纵就没在驱动结果。</span>离散驱动元：放弃密度图，用质量点局部随机化：精确随机化推断出 \\(p\\) 值，协变量平衡作随机化成立与否的检查。多门槛：逐个门槛报，再按门槛处样本份额池化，池化前后结论不同要解释。模糊断点：门槛 IV，估计对象是门槛邻域内依从者的效应——这个对象叫什么，下一课展开，本课只把第一阶段在 \\(c\\) 的跳当第一阶段报。报告清单：带宽敏感、协变量平衡、密度或质量点图、donut、聚类层级。</p>',9)),(A(),B(o,null,{default:e(()=>[d(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20RV%7B%22%E9%A9%B1%E5%8A%A8%E5%85%83%E8%BF%9E%E7%BB%AD%3F%22%7D%20--%3E%7C%E6%98%AF%7C%20CCT%5B%22CCT%20%E5%81%8F%E8%AF%AF%E6%A0%A1%E6%AD%A3%E4%B8%8E%E5%B8%A6%E5%AE%BD%22%5D%0A%20%20CCT%20--%3E%20SENS%5B%22h%20%E4%B8%8E%E5%8D%8A%E5%80%8D%E4%B8%A4%E5%80%8D%E6%95%8F%E6%84%9F%E6%80%A7%22%5D%0A%20%20CCT%20--%3E%20DON%5B%22donut%20%E7%A8%B3%E5%81%A5%E6%80%A7%22%5D%0A%20%20RV%20--%3E%7C%E7%A6%BB%E6%95%A3%7C%20MASS%5B%22%E8%B4%A8%E9%87%8F%E7%82%B9%E5%B1%80%E9%83%A8%E9%9A%8F%E6%9C%BA%E5%8C%96%22%5D%0A%20%20MASS%20--%3E%20EXACT%5B%22%E7%B2%BE%E7%A1%AE%E9%9A%8F%E6%9C%BA%E5%8C%96%20p%20%E5%80%BC%E4%B8%8E%E5%B9%B3%E8%A1%A1%22%5D%0A%20%20SENS%20--%3E%20REP%5B%22%E6%8A%A5%E5%91%8A%3A%20%E6%95%8F%E6%84%9F%2F%E5%B9%B3%E8%A1%A1%2F%E5%AF%86%E5%BA%A6%2Fdonut%22%5D%0A%20%20EXACT%20--%3E%20REP%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[n("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"机制仍是局部随机：在 \\(c\\) 的邻域谁略高谁略低像抛硬币。加深后的每一件工具都是对这一句话的一次攻击——密度图攻击「能否精确操纵」，协变量 bundle 攻击「是否还有没看到的排序」，donut 攻击「操纵恰好在门槛上」，质量点检验把抛硬币改成有限格点的抽签。带宽的账也在机制上：偏误来自门槛两侧曲率差，方差来自局部样本量，CCT 把偏误估计进置信区间，敏感性报告则让读者看到偏误-方差权衡本身。",-1)),E[5]||(E[5]=a("p",null,"不这么做会错在哪：只报一个带宽的估计，把权衡藏起来；离散驱动元硬画密度图，检验对象不存在；把 \\(\\tau_{\\mathrm{SRD}}\\) 写成「该政策的效果」，一英寸被偷换成全国。",-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"常见误区：初学者容易把门槛处的效应直接乘全国人数算总收益。\\(\\tau_{\\mathrm{SRD}}\\) 的局部随机只在 \\(c\\) 的一英寸内成立，全局乘数隐含「效应在整个人群分布上处处相同」的外推假设——这个假设要显式写出来并辩护；漏写时，数字被推宽多少全凭运气。")],-1)),(A(),B(o,null,{default:e(()=>[d(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%A4%B1%E6%95%88%E6%A8%A1%E5%BC%8F%201%3A%20%E5%8F%AF%E6%93%8D%E7%BA%B5%E4%B8%94%E6%83%B3%E6%93%8D%E7%BA%B5%22%5D%20--%3E%20M%5B%22McCrary%20%E5%AF%86%E5%BA%A6%E8%B7%B3%E5%8F%98%E6%A3%80%E9%AA%8C%22%5D%0A%20%20B%5B%22%E5%A4%B1%E6%95%88%E6%A8%A1%E5%BC%8F%202%3A%20%E7%A0%94%E7%A9%B6%E8%80%85%E6%B2%A1%E8%A7%81%E8%BF%87%E7%9A%84%E6%8E%92%E5%BA%8F%22%5D%20--%3E%20C%5B%22%E5%8D%8F%E5%8F%98%E9%87%8F%20bundle%20%E5%B9%B3%E8%A1%A1%22%5D%0A%20%20D%5B%22%E5%A4%B1%E6%95%88%E6%A8%A1%E5%BC%8F%203%3A%20%E6%93%8D%E7%BA%B5%E6%81%B0%E5%9C%A8%E9%97%A8%E6%A7%9B%E4%B8%8A%22%5D%20--%3E%20E%5B%22donut%20%E6%8C%96%E6%8E%89%E4%B8%AD%E5%BF%83%E5%86%8D%E4%BC%B0%22%5D%0A%20%20F%5B%22%E5%A4%B1%E6%95%88%E6%A8%A1%E5%BC%8F%204%3A%20%E9%A9%B1%E5%8A%A8%E5%85%83%E7%A6%BB%E6%95%A3%E6%97%A0%E9%82%BB%E5%B1%85%22%5D%20--%3E%20G%5B%22%E8%B4%A8%E9%87%8F%E7%82%B9%E7%B2%BE%E7%A1%AE%E9%9A%8F%E6%9C%BA%E5%8C%96%E6%8E%A8%E6%96%AD%22%5D%0A%20%20M%20--%3E%20H%5B%22%E6%AF%8F%E4%BB%B6%E5%B7%A5%E5%85%B7%E5%8F%AA%E7%9B%96%E8%87%AA%E5%B7%B1%E9%82%A3%E6%9D%A1%2C%20%E6%A3%80%E9%AA%8C%E8%A6%81%E6%89%93%E5%8C%85%22%5D%0A%20%20C%20--%3E%20H%0A%20%20E%20--%3E%20H%0A%20%20G%20--%3E%20H%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=r('<p>上图回答的问题是「操纵检验为什么必须是 bundle」：方法图按驱动元分岔给流程，这张把四种失效模式与四件工具一一对接——每件检验都只覆盖自己的那条威胁，任何一件通过都不等于局部随机成立，打包互证才是设计报告的完整形态。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不做全局外推的代数，kink 设计与地理边界断点只标接口；协变量条件化的进一步方法不展开。模糊断点的估计对象留到下一课——那是工具变量在异质效应下的正题。外推需要结构模型时，接口在结构估计的课，不在本课。断点的诚实口径：这里识别的是门槛处的处理效应，加多少外推假设，就宽多少，假设要写在数字旁边。</p><p>后课默认：RDD 报告带敏感性 bundle；门槛 IV 的对象与 LATE 语言下一课接走。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>带宽敏感性是设计报告的一部分，不是一个稳健性脚注。</li><li>操纵检验是 bundle：密度、协变量平衡、donut，互为补充。</li><li>离散驱动元换局部随机化推断，密度检验失效。</li><li>\\(\\tau\\) 只在门槛处；外推幅度等于外加假设的幅度，要声明。</li><li>出处：Imbens and Kalyanaraman, <em>REStud</em> 2012；Calonico, Cattaneo and Titiunik, <em>Econometrica</em> 2014；Cattaneo, Frandsen and Titiunik 2015；Gelman and Imbens 2019。</li></ul>',6))])}const b=l(p,[["render",C]]);export{T as __pageData,b as default};
